app.querySelectorAll('[data-upload-hero]').forEach(i=>i.onchange=()=>upload(i.files[0]).then(url=>{const card=i.closest('[data-hero-card]'),input=card.querySelector('[name^="hero"]'),img=card.querySelector('[data-media-preview]');input.value=url;img.src=url;toast('Slayt görseli yüklendi.')} ).catch(e=>toast(e.message,true)));
app.querySelectorAll('[data-media-path]').forEach(i=>i.addEventListener('input',()=>{const img=i.closest('.media-edit-card,.field')?.querySelector('[data-media-preview]');if(img)img.src=i.value}));
